INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.1', '{"id":"5.1","title":"Project-based learning","group":"Pedagogical approaches","source":"Annexure-5.1.docx","description":"List of projects assigned to final-year students, their guides, and supporting reports.","fields":[{"label":"Name of Project guide","type":"text","required":true},{"label":"Name of students","type":"textarea","required":true},{"label":"Student Roll Number(s)","type":"text","required":false},{"label":"Title of the project","type":"text","required":true},{"label":"Broader subject area covered","type":"text","required":true},{"label":"Whether collaborative / interdisciplinary","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Whether report is available","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Does it support flipped learning","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"If yes, kindly mention how","type":"textarea","required":true,"when":["Does it support flipped learning","Yes"]},{"label":"Project Type","type":"select","options":["Final-year project","Mini project","Research project","Other"],"required":false},{"label":"Interdisciplinary Project","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Collaborative Project","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Collaborating Department","type":"text","required":false},{"label":"Collaborating Institute","type":"text","required":false},{"label":"Collaborating Industry","type":"text","required":false},{"label":"Brief Project Description","type":"textarea","required":false},{"label":"Current Status","type":"select","options":["Planned","In progress","Completed"],"required":false},{"label":"Is the project report available in the library?","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Library reference/details","type":"text","required":false,"when":["Is the project report available in the library?","Yes"]},{"label":"Location","type":"text","required":false,"when":["Is the project report available in the library?","Yes"]},{"label":"Report number if applicable","type":"text","required":false,"when":["Is the project report available in the library?","Yes"]}],"evidence":["Project Report","Project List","Guide Allocation Document","Collaboration Evidence","Other Supporting Documents"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.2', '{"id":"5.2","title":"Flipped classroom","group":"Pedagogical approaches","description":"Record subject-wise flipped-learning activities. The original Annexure 5.2 template was not supplied.","fields":[{"label":"Subject Name","type":"text","required":true},{"label":"Subject Code","type":"text","required":false},{"label":"Faculty Name","type":"text","required":true},{"label":"Semester","type":"text","required":false},{"label":"Topic where flipped learning was implemented","type":"text","required":true},{"label":"Methodology used","type":"multi","options":["Students studied textbook derivations before class and doubts were clarified during class","Problems were given as assignments","Coding assignments were completed in laboratories","Student seminar/presentation","Other"]},{"label":"Description of implementation","type":"textarea","required":false},{"label":"Number of participating students","type":"number","required":false},{"label":"Learning activity","type":"textarea","required":false},{"label":"Outcome/observation","type":"textarea","required":false}],"evidence":["Lesson Plan","Laboratory Manual","Assignment","Seminar Report","Seminar PPT","Attendance","Photographs","Other Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.3', '{"id":"5.3","title":"Student seminars","group":"Pedagogical approaches","source":"Annexure-5.3.docx","description":"Brief report of seminars conducted as part of the student curriculum.","fields":[{"label":"Seminar topic","type":"text","required":true},{"label":"Name of students","type":"textarea","required":true},{"label":"Name of guide","type":"text","required":true},{"label":"Broader subject area","type":"text","required":true},{"label":"Whether seminar report/ PPT is preserved?","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Subject Name","type":"text","required":false},{"label":"Subject Code","type":"text","required":false},{"label":"Semester","type":"text","required":false},{"label":"Seminar Date","type":"date","required":false},{"label":"Number of participating students","type":"number","required":false},{"label":"Description of implementation","type":"textarea","required":false},{"label":"Outcome/observation","type":"textarea","required":false}],"evidence":["Seminar Report","Seminar PPT","Attendance","Photographs","Other Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.4', '{"id":"5.4","title":"Application to abstract","group":"Pedagogical approaches","source":"Annexure-5.4.docx","description":"Explain how hardware laboratory experiments help students understand theoretical concepts.","fields":[{"label":"Name of laboratory","type":"text","required":true},{"label":"Name of experiment","type":"text","required":true},{"label":"Whether implementing the concept","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"If yes How?","type":"textarea","required":true,"when":["Whether implementing the concept","Yes"]},{"label":"Subject Name","type":"text","required":false},{"label":"Subject Code","type":"text","required":false},{"label":"Faculty Name","type":"text","required":false},{"label":"Theoretical Concept","type":"text","required":false},{"label":"Explanation of how laboratory work helps students understand the theoretical concept","type":"textarea","required":false},{"label":"Student learning outcome","type":"textarea","required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Laboratory Manual","Lesson Plan","Photographs","Other Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.5', '{"id":"5.5","title":"VSK & multimedia support","group":"Pedagogical approaches","description":"Classroom and laboratory facilities. Original Annexure 5.5 template was not supplied.","fields":[{"label":"Room/Laboratory Name","type":"text","required":true},{"label":"Room Number","type":"text","required":false},{"label":"Type of Facility","type":"select","options":["Classroom","Laboratory","Seminar hall","Other"],"required":false},{"label":"Smart Board","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Projector","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Computer","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Internet Facility","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Audio System","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Video/Multimedia Facility","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Other Technology","type":"text","required":false},{"label":"Subjects/Activities Using the Facility","type":"text","required":false},{"label":"Frequency of Use","type":"select","options":["Daily","Weekly","Monthly","Occasionally"],"required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Photographs","Facility Inventory","Supporting Documents"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.6', '{"id":"5.6","title":"Internships & field projects","group":"Experiential learning","source":"Annexure-5.6.docx","description":"Year-wise internship records with tenure, payment status, and preserved industry documents.","fields":[{"label":"Name of students","type":"text","required":true},{"label":"Roll Number","type":"text","required":false},{"label":"Year/Semester","type":"text","required":false},{"label":"Name of company/ institute","type":"text","required":true},{"label":"Tenure of internship","type":"text","required":true},{"label":"Paid/ un paid","type":"select","options":["Paid","Unpaid"],"required":true},{"label":"Does department has all relevant documents?","type":"select","options":["Yes","No","Not Applicable"],"required":false},{"label":"Internship Title","type":"text","required":false},{"label":"Internship Type","type":"text","required":false},{"label":"Start Date","type":"date","required":false},{"label":"End Date","type":"date","required":false},{"label":"Location","type":"text","required":false},{"label":"Faculty Coordinator","type":"text","required":false},{"label":"Brief Description","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false}],"evidence":["Appointment/Offer Letter","Internship Completion Certificate","Internship Report","Release Letter","Industry Certificate","Photographs","Other Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.7', '{"id":"5.7","title":"Slow & advanced learners","group":"Catering to diversity","source":"Annexure-5.7.docx","description":"Record individual learner support, previous and present grades, and signed evidence.","fields":[{"label":"Name of student","type":"text","required":true},{"label":"Name of faculty member","type":"text","required":true},{"label":"Name of subject","type":"text","required":true},{"label":"Topic covered","type":"text","required":true},{"label":"Previous grade","type":"text","required":false},{"label":"Present grade","type":"text","required":false},{"label":"Signature of the student","type":"signature","required":false},{"label":"Signature of the faculty member","type":"signature","required":false},{"label":"Student Category","type":"select","options":["Slow Learner","Advanced Learner","Backlog Student","Other"],"required":true},{"label":"Type of Intervention","type":"multi","options":["Remedial Classes","Additional Tutorials","Mentoring","Extra Assignments","Advanced Problems","Additional Learning Resources","Other Intervention"]},{"label":"Number of Students","type":"number","required":false},{"label":"Description of Action","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Student Results","Attendance","Improvement Evidence","Signature of the student","Signature of the faculty member","Supporting Documents"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.8', '{"id":"5.8","title":"Adaptive teaching methods","group":"Catering to diversity","description":"State-of-the-art topics, teaching methods, and relevant library resources. Template not supplied.","fields":[{"label":"Subject","type":"text","required":true},{"label":"Faculty","type":"text","required":true},{"label":"Topic","type":"text","required":true},{"label":"Within Curriculum / Beyond Curriculum","type":"select","options":["Within Curriculum","Beyond Curriculum"],"required":false},{"label":"Reason for Selection","type":"textarea","required":false},{"label":"Teaching Method","type":"textarea","required":false},{"label":"Number of Students","type":"number","required":false},{"label":"Learning Outcome","type":"textarea","required":false},{"label":"Book Title","type":"text","required":false},{"label":"Author","type":"text","required":false},{"label":"Publisher","type":"text","required":false},{"label":"Library Accession Number","type":"text","required":false},{"label":"Availability","type":"select","options":["Available","Unavailable","On order"],"required":false}],"evidence":["Attendance","Lesson Plan","Geotagged Photos","Teaching Material","Library Evidence","Other Documents"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.9a', '{"id":"5.9a","title":"SWAYAM / online courses","group":"Skill development & support","description":"Annexure 5.9 · Student course enrollments, results, and certificates. Template not supplied.","fields":[{"label":"Student Name","type":"text","required":true},{"label":"Roll Number","type":"text","required":false},{"label":"SWAYAM/NPTEL Course","type":"text","required":true},{"label":"Course Provider","type":"text","required":false},{"label":"Duration","type":"text","required":false},{"label":"Enrollment Status","type":"select","options":["Enrolled","Not enrolled","Withdrawn"],"required":false},{"label":"Completion Status","type":"select","options":["In progress","Completed","Not completed"],"required":false},{"label":"Result/Grade","type":"text","required":false},{"label":"Certificate Available","type":"select","options":["Yes","No","Not Applicable"],"required":false}],"evidence":["Enrollment Evidence","Certificate","Result","Other Documents"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.9b', '{"id":"5.9b","title":"Seminars & talks","group":"Skill development & support","description":"Annexure 5.9 · Talks organized for skill development. Template not supplied.","fields":[{"label":"Seminar/Talk Title","type":"text","required":true},{"label":"Date","type":"date","required":false},{"label":"Speaker","type":"text","required":true},{"label":"Speaker Organization","type":"text","required":false},{"label":"Topic","type":"text","required":false},{"label":"Number of Students","type":"number","required":false},{"label":"Description","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false}],"evidence":["Invitation Letter","Leaflet/Brochure","Attendance","Geotagged Photos","Presentation","Report"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.10', '{"id":"5.10","title":"Industrial training","group":"Industry–academia linkage","description":"Student and faculty training with industry. Template not supplied.","fields":[{"label":"Student/Faculty Name","type":"text","required":true},{"label":"Industry","type":"text","required":true},{"label":"Training Title","type":"text","required":true},{"label":"Duration","type":"text","required":false},{"label":"Start Date","type":"date","required":false},{"label":"End Date","type":"date","required":false},{"label":"Description","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false}],"evidence":["Training Certificate","Attendance","Report","Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.11', '{"id":"5.11","title":"Industry collaborative projects","group":"Industry–academia linkage","description":"Projects undertaken in collaboration with industry. Template not supplied.","fields":[{"label":"Project Title","type":"text","required":true},{"label":"Student(s)","type":"textarea","required":true},{"label":"Faculty Guide","type":"text","required":false},{"label":"Industry Name","type":"text","required":true},{"label":"Industry Contact","type":"text","required":false},{"label":"Project Duration","type":"text","required":false},{"label":"Description","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false}],"evidence":["Supporting Documents","Project Report","Collaboration Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.12', '{"id":"5.12","title":"Industry programs & talks","group":"Industry–academia linkage","description":"Joint programs and invited industry talks. Template not supplied.","fields":[{"label":"Program/Talk Name","type":"text","required":true},{"label":"Industry","type":"text","required":true},{"label":"Speaker","type":"text","required":false},{"label":"Date","type":"date","required":false},{"label":"Participants","type":"number","required":false},{"label":"Description","type":"textarea","required":false},{"label":"Outcome","type":"textarea","required":false}],"evidence":["Evidence","Attendance","Invitation Letter","Photographs"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('5.13', '{"id":"5.13","title":"MoUs with industries","group":"Industry–academia linkage","description":"Industry agreements, validity, and activities. Template not supplied.","fields":[{"label":"Industry/Organization","type":"text","required":true},{"label":"MoU Title","type":"text","required":true},{"label":"Date Signed","type":"date","required":false},{"label":"Validity","type":"text","required":false},{"label":"Purpose","type":"textarea","required":false},{"label":"Activities Conducted","type":"textarea","required":false},{"label":"Current Status","type":"select","options":["Active","Expired","Under renewal"],"required":false}],"evidence":["Supporting MoU Document","Activity Evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('assessment', '{"id":"assessment","title":"Assessment","group":"Institutional information","description":"Assessment practices according to university policy.","fields":[{"label":"Assessment Type","type":"text","required":true},{"label":"Applicable University Policy","type":"text","required":true},{"label":"Description","type":"textarea","required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Supporting Document","University Policy"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('grievance', '{"id":"grievance","title":"Academic grievance redressal","group":"Institutional information","description":"Feedback committee and examination cell records.","fields":[{"label":"Type of Academic Grievance","type":"text","required":true},{"label":"Number of Cases","type":"number","required":true},{"label":"Source of Data","type":"text","required":false},{"label":"Action Taken","type":"textarea","required":false},{"label":"Status","type":"select","options":["Open","In progress","Resolved"],"required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Feedback Committee Report","Examination Cell Paper Review Report","Other relevant evidence"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.naac_panel_definitions (id, definition) VALUES ('gender', '{"id":"gender","title":"Gender equality","group":"Institutional information","description":"Office/coordinator records of gender-equality initiatives.","fields":[{"label":"Activity/Initiative","type":"text","required":true},{"label":"Date","type":"date","required":false},{"label":"Description","type":"textarea","required":false},{"label":"Number of Participants","type":"number","required":false},{"label":"Outcome","type":"textarea","required":false},{"label":"Remarks","type":"textarea","required":false}],"evidence":["Supporting Evidence","Attendance","Photographs"]}'::jsonb) ON CONFLICT (id) DO NOTHING;
